"""Images and videos generated by the AI assistant, stored in media/temp and served at /api/media/temp/<file>.

- render_map:   PNG of a map visual: Esri basemap + GeoServer raster (clipped to an uploaded area when set) + villages
                coloured by the visual's values, highlighted villages, the uploaded area outline, title and legends.
- render_chart: PNG of a bar or donut chart visual.
- animate:      a sequence of map frames as an animated GIF (and MP4 when imageio-ffmpeg is installed).
Files older than KEEP_DAYS are removed whenever a new one is written."""
import io
import math
import time
import urllib.parse
import uuid
from concurrent.futures import ThreadPoolExecutor
from functools import lru_cache

import httpx
import shapely
from PIL import Image, ImageDraw, ImageFont

from app.api.service.geoserver_svc import factors
from app.api.service.geoserver_svc.geoserver import ows_get
from app.conf.logging.applog import logger
from app.conf.settings import settings

TEMP_DIR = settings.MEDIA_DIR / "temp"
URL_PREFIX = "/api/media/temp"
KEEP_DAYS = 7
WIDTH = 1200
R = 6378137.0
BASEMAP = "https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/export"
RAMPS = {
    "reds": ["#ffffb2", "#fecc5c", "#fd8d3c", "#f03b20", "#bd0026"],
    "oranges": ["#feedde", "#fdbe85", "#fd8d3c", "#e6550d", "#a63603"],
    "blues": ["#eff3ff", "#bdd7e7", "#6baed6", "#3182bd", "#08519c"],
    "greens": ["#edf8e9", "#bae4b3", "#74c476", "#31a354", "#006d2c"],
    "purples": ["#f2f0f7", "#cbc9e2", "#9e9ac8", "#756bb1", "#54278f"],
    "browns": ["#fff7bc", "#fee391", "#fec44f", "#ec7014", "#993404"],
    "greys": ["#f7f7f7", "#cccccc", "#969696", "#636363", "#252525"],
}
PALETTE = ["#1d6996", "#cc503e", "#0f8554", "#edad08", "#5f4690", "#38a6a5", "#e17c05", "#73af48", "#94346e", "#666666"]


# ---------- storage ----------

def _cleanup():
    cutoff = time.time() - KEEP_DAYS * 86400
    for f in TEMP_DIR.glob("*"):
        try:
            if f.is_file() and f.stat().st_mtime < cutoff:
                f.unlink()
        except OSError:
            pass


def save(data: bytes, ext: str) -> str:
    """Writes a generated file to media/temp; returns its URL."""
    TEMP_DIR.mkdir(parents=True, exist_ok=True)
    _cleanup()
    name = f"{uuid.uuid4().hex[:16]}.{ext}"
    (TEMP_DIR / name).write_bytes(data)
    return f"{URL_PREFIX}/{name}"


def _png(img: Image.Image) -> bytes:
    out = io.BytesIO()
    img.convert("RGB").save(out, format="PNG", compress_level=6)
    return out.getvalue()


# ---------- drawing helpers ----------

@lru_cache(maxsize=16)
def _font(size: int):
    return ImageFont.load_default(size=size)


def _t(text: str) -> str:
    """Characters the built-in font lacks (they would print as boxes)."""
    return (str(text).replace("–", "-").replace("—", "-").replace("₂", "2").replace("“", '"').replace("”", '"')
            .replace("’", "'"))


def _rgb(hex_color: str) -> tuple[int, int, int]:
    h = hex_color.lstrip("#")
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)


def _interpolate(stops: list[str], t: float) -> tuple[int, int, int]:
    t = min(1.0, max(0.0, t if math.isfinite(t) else 0.0))
    pos = t * (len(stops) - 1)
    i = min(int(pos), len(stops) - 2)
    a, b, f = _rgb(stops[i]), _rgb(stops[i + 1]), pos - i
    return tuple(round(a[k] + (b[k] - a[k]) * f) for k in range(3))


def _fmt(v: float | None, nd: int = 1) -> str:
    return "–" if v is None else f"{v:,.{nd}f}"


def _merc(lon: float, lat: float) -> tuple[float, float]:
    lat = max(-85.0, min(85.0, lat))
    return R * math.radians(lon), R * math.log(math.tan(math.pi / 4 + math.radians(lat) / 2))


# ---------- maps ----------

class _Frame:
    """Pixel frame of a Web Mercator bounding box."""

    def __init__(self, bounds: tuple[float, float, float, float], width: int = WIDTH):
        minx, miny = _merc(bounds[0], bounds[1])
        maxx, maxy = _merc(bounds[2], bounds[3])
        pad = max(maxx - minx, maxy - miny) * 0.06 or 500
        self.x0, self.y0, self.x1, self.y1 = minx - pad, miny - pad, maxx + pad, maxy + pad
        self.w = width
        self.h = max(300, min(1400, round(width * (self.y1 - self.y0) / (self.x1 - self.x0))))
        # keep the aspect ratio exact after clamping the height
        cy, half = (self.y0 + self.y1) / 2, (self.x1 - self.x0) * self.h / self.w / 2
        self.y0, self.y1 = cy - half, cy + half

    @property
    def bbox(self) -> str:
        return f"{self.x0},{self.y0},{self.x1},{self.y1}"

    def px(self, lon: float, lat: float) -> tuple[float, float]:
        x, y = _merc(lon, lat)
        return (x - self.x0) / (self.x1 - self.x0) * self.w, (self.y1 - y) / (self.y1 - self.y0) * self.h

    def rings(self, geom):
        """Exterior rings of a (multi)polygon as pixel point lists."""
        for poly in getattr(geom, "geoms", [geom]):
            if poly.geom_type == "Polygon" and not poly.is_empty:
                yield [self.px(x, y) for x, y in poly.exterior.coords]


@lru_cache(maxsize=16)
def _basemap_bytes(bbox: str, w: int, h: int) -> bytes:
    r = httpx.get(BASEMAP, params={"bbox": bbox, "bboxSR": 3857, "imageSR": 3857, "size": f"{w},{h}",
                                   "format": "png", "f": "image"}, timeout=30)
    r.raise_for_status()
    return r.content


def _basemap(frame: _Frame) -> Image.Image:
    """Esri street basemap for the frame (cached: animation frames share one download)."""
    try:
        data = _basemap_bytes(frame.bbox, frame.w, frame.h)
        return Image.open(io.BytesIO(data)).convert("RGBA").resize((frame.w, frame.h))
    except Exception:
        logger.warning("Assistant media: basemap unavailable, using a plain background")
        return Image.new("RGBA", (frame.w, frame.h), (244, 246, 245, 255))


def _wms(frame: _Frame, raster: dict) -> Image.Image | None:
    params = {"service": "WMS", "version": "1.1.1", "request": "GetMap", "layers": raster["layer"], "styles": "",
              "srs": "EPSG:3857", "bbox": frame.bbox, "width": frame.w, "height": frame.h,
              "format": "image/png", "transparent": "true"}
    if raster.get("clip"):
        params["clip"] = raster["clip"]
    try:
        data = ows_get(f"/{raster['workspace']}/wms?{urllib.parse.urlencode(params)}")
        return Image.open(io.BytesIO(data)).convert("RGBA")
    except Exception:
        logger.warning("Assistant media: raster %s unavailable", raster.get("layer"))
        return None


def _legend_image(raster: dict) -> Image.Image | None:
    q = urllib.parse.urlencode({"service": "WMS", "request": "GetLegendGraphic", "format": "image/png", "layer": raster["layer"]})
    try:
        return Image.open(io.BytesIO(ows_get(f"/{raster['workspace']}/wms?{q}"))).convert("RGBA")
    except Exception:
        return None


def _map_bounds(visual: dict, shapes: dict) -> tuple[float, float, float, float]:
    focus = [shapes[c] for c in visual.get("focus") or [] if c in shapes]
    if focus:
        return shapely.total_bounds(focus)
    if visual.get("area"):
        return shapely.geometry.shape(visual["area"]["geometry"]).bounds
    return shapely.total_bounds(list(shapes.values()))


def render_map(visual: dict, title: str | None = None, width: int = WIDTH) -> bytes:
    shapes = factors._village_shapes()
    frame = _Frame(_map_bounds(visual, shapes), width)
    img = _basemap(frame)
    values = visual.get("values") or {}
    highlight = set(visual.get("highlight") or [])
    raster = visual.get("raster")

    # Villages: coloured by value (or outlines only), drawn under the raster when both are shown.
    overlay = Image.new("RGBA", img.size, (0, 0, 0, 0))
    draw = ImageDraw.Draw(overlay)
    stops = RAMPS.get((visual.get("metric") or {}).get("ramp") or "reds", RAMPS["reds"])
    vals = [float(v) for v in values.values() if v is not None]
    lo, hi = (min(vals), max(vals)) if vals else (0.0, 0.0)
    codes = values.keys() if values else shapes.keys()
    for code in codes:
        geom = shapes.get(code)
        if geom is None:
            continue
        for ring in frame.rings(geom):
            if values:
                v = values.get(code)
                fill = (*(_interpolate(stops, (v - lo) / (hi - lo)) if hi > lo else _rgb(stops[2])), 200 if not highlight else 140)
                draw.polygon(ring, fill=fill, outline=(69, 90, 100, 200))
            else:
                draw.line(ring, fill=(69, 90, 100, 150), width=1)
    img = Image.alpha_composite(img, overlay)
    if raster:
        layer = _wms(frame, raster)
        if layer:
            if values:  # half transparent over a thematic map
                layer.putalpha(layer.getchannel("A").point(lambda a: int(a * 0.75)))
            img = Image.alpha_composite(img, layer)

    top = ImageDraw.Draw(img)
    for code in highlight:
        if code in shapes:
            for ring in frame.rings(shapes[code]):
                top.line(ring, fill=(13, 71, 161, 255), width=4)
    if visual.get("area"):
        for ring in frame.rings(shapely.geometry.shape(visual["area"]["geometry"])):
            top.line(ring, fill=(26, 35, 126, 255), width=4)

    # Title bar
    title = title or visual.get("title") or "Map"
    bar = 46
    canvas = Image.new("RGBA", (img.width, img.height + bar), (255, 255, 255, 255))
    canvas.paste(img, (0, bar))
    d = ImageDraw.Draw(canvas)
    d.text((14, 12), _t(title)[:110], fill=(31, 42, 51), font=_font(20))

    # Legend (bottom right): thematic ramp and/or raster legend
    blocks: list[Image.Image] = []
    if values and hi > lo:
        lg = Image.new("RGBA", (260, 64), (255, 255, 255, 235))
        ld = ImageDraw.Draw(lg)
        metric = visual.get("metric") or {}
        ld.text((10, 6), _t(f"{metric.get('label', '')} ({metric.get('unit', '')})")[:38], fill=(38, 50, 56), font=_font(13))
        for x in range(240):
            ld.line([(10 + x, 26), (10 + x, 38)], fill=_interpolate(stops, x / 239))
        ld.text((10, 42), _fmt(lo), fill=(84, 110, 122), font=_font(12))
        ld.text((250 - ld.textlength(_fmt(hi), font=_font(12)), 42), _fmt(hi), fill=(84, 110, 122), font=_font(12))
        blocks.append(lg)
    if raster:
        legend = _legend_image(raster)
        if legend:
            lg = Image.new("RGBA", (max(legend.width, 200) + 20, legend.height + 30), (255, 255, 255, 235))
            ImageDraw.Draw(lg).text((10, 6), _t(raster.get("title", ""))[:34], fill=(38, 50, 56), font=_font(13))
            lg.alpha_composite(legend, (10, 26))
            blocks.append(lg)
    y = canvas.height - 12
    for b in reversed(blocks):
        y -= b.height
        canvas.alpha_composite(b, (canvas.width - b.width - 12, max(bar + 6, y)))
        y -= 8
    d.text((12, canvas.height - 20), "Basemap: Esri, HERE, Garmin, OpenStreetMap contributors · Varanasi Carbon Dashboard",
           fill=(96, 125, 139), font=_font(11))
    return _png(canvas)


# ---------- charts ----------

def render_chart(visual: dict) -> bytes:
    data = visual.get("data") or []
    w = 1000
    if visual.get("chart") == "donut":
        h = 560
        img = Image.new("RGB", (w, h), "white")
        d = ImageDraw.Draw(img)
        d.text((20, 16), _t(visual.get("title", ""))[:90], fill=(31, 42, 51), font=_font(20))
        total = sum(float(x["value"]) for x in data) or 1
        box, start = (60, 80, 500, 520), -90.0
        for i, x in enumerate(data):
            sweep = 360 * float(x["value"]) / total
            d.pieslice(box, start, start + sweep, fill=PALETTE[i % len(PALETTE)], outline="white", width=2)
            start += sweep
        d.ellipse((170, 190, 390, 410), fill="white")
        for i, x in enumerate(data):
            y = 110 + i * 36
            d.rectangle((560, y, 580, y + 20), fill=PALETTE[i % len(PALETTE)])
            d.text((592, y), _t(f"{x['name']}: {_fmt(float(x['value']))} ({100 * float(x['value']) / total:.1f}%)"),
                   fill=(38, 50, 56), font=_font(16))
        return _png(img)

    # Bar chart (horizontal bars, first series)
    series = (visual.get("series") or [{"key": "value"}])
    key, cat = series[0]["key"], visual.get("category") or "name"
    rows = [(_t(x.get(cat, "")), float(x.get(key) or 0)) for x in data][:25]
    h = 90 + 34 * len(rows)
    img = Image.new("RGB", (w, h), "white")
    d = ImageDraw.Draw(img)
    d.text((20, 16), _t(visual.get("title", ""))[:90], fill=(31, 42, 51), font=_font(20))
    vmax = max((v for _, v in rows), default=1) or 1
    left, right = 280, w - 120
    for i, (name, v) in enumerate(rows):
        y = 64 + i * 34
        d.text((left - 10 - d.textlength(name[:30], font=_font(15)), y + 4), name[:30], fill=(38, 50, 56), font=_font(15))
        d.rectangle((left, y, left + (right - left) * v / vmax, y + 24), fill=PALETTE[0])
        d.text((left + (right - left) * v / vmax + 8, y + 4), _fmt(v), fill=(38, 50, 56), font=_font(14))
    return _png(img)


# ---------- animation ----------

def animate(frames: list[tuple[dict, str]], seconds_per_frame: float = 1.6) -> dict:
    """Renders map frames (visual, caption) into an animated GIF, plus an MP4 when imageio-ffmpeg is available."""
    with ThreadPoolExecutor(max_workers=4) as pool:  # frames render in parallel (same cached basemap)
        pngs = list(pool.map(lambda f: render_map(f[0], f[1], width=900), frames))
    images = [Image.open(io.BytesIO(p)).convert("RGB") for p in pngs]
    out = io.BytesIO()
    images[0].save(out, format="GIF", save_all=True, append_images=images[1:], duration=int(seconds_per_frame * 1000),
                   loop=0, optimize=True)
    result = {"gif": save(out.getvalue(), "gif"), "mp4": None, "frames": len(images)}
    try:
        import imageio.v3 as iio
        import numpy as np
        w, h = (d // 2 * 2 for d in images[0].size)  # even size for H.264
        repeat = max(1, round(seconds_per_frame * 2))  # 2 fps output
        stack = [np.asarray(im.resize((w, h))) for im in images for _ in range(repeat)]
        result["mp4"] = save(iio.imwrite("<bytes>", stack, extension=".mp4", fps=2), "mp4")
    except Exception as e:  # imageio[ffmpeg] not installed: GIF only
        logger.info("Assistant media: MP4 skipped (%s)", type(e).__name__)
    return result
